import sys
sys.setrecursionlimit(10000)
adj = [[] for _ in range(36)]
deltas = [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]
for a in range(36):
    r,c = divmod(a,6)
    for dr,dc in deltas:
        nr,nc = r+dr, c+dc
        if 0<=nr<6 and 0<=nc<6:
            adj[a].append(nr*6+nc)
fixed = {3:17, 6:24, 17:30, 19:6, 29:25, 32:21, 34:23}
path = [None]*36
path[0] = 0
visited = set([0])
def solve(step):
    if step == 36:
        return True
    candidates = [fixed[step]] if step in fixed else adj[path[step-1]]
    for nxt in candidates:
        if nxt not in visited and (step == 0 or nxt in adj[path[step-1]]):
            path[step] = nxt
            visited.add(nxt)
            if solve(step+1):
                return True
            visited.remove(nxt)
            path[step] = None
    return False
if solve(1):
    print(path)
else:
    print("UNSATISFIABLE")
